SELECT t.id AS taskId, t.report_no AS reportNo, t.status AS status, t.message AS reportRemark, t.lifecycle_status AS lifecycleStatus, t.inspection_order_id AS inspectionOrderId, io.order_no AS orderNo, io.order_status AS orderStatus, io.batch_no AS batchNo, io.production_date AS productionDate, io.material_id AS materialId, m.name AS materialName, m.code AS materialCode, m.specification AS materialSpec, m.unit_id AS unitId, io.scheme_version_id AS schemeVersionId, s.name AS schemeName, sv.version_no AS schemeVersionNo, io.remark AS orderRemark, io.finished AS orderFinished, io.finished_time AS orderFinishedTime, io.create_by AS createBy, io.create_time AS createTime, io.create_by AS requestUserId, io.create_time AS requestTime, io.template_id AS orderTemplateId, dc.name AS orderTemplateName, io.terminate_reason AS terminateReason, io.terminate_time AS terminateTime, t.template_version_id AS templateVersionId, v.template_id AS templateId, v.version_no AS templateVersionNo, t.path AS path, t.end_time AS endTime, t.report_approved AS reportApproved, t.report_approval_time AS reportApprovalTime, t.create_by AS generatedBy FROM lm_report_generate_task t LEFT JOIN lm_inspection_order io ON io.id = t.inspection_order_id LEFT JOIN lm_report_template_version v ON v.id = t.template_version_id LEFT JOIN lm_inspect_material m ON io.material_id = m.id LEFT JOIN lm_inspection_scheme_version sv ON io.scheme_version_id = sv.id LEFT JOIN lm_inspection_scheme s ON sv.scheme_id = s.id LEFT JOIN lm_document_config dc ON io.template_id = dc.id
t.is_deleted = 0 AND t.status = 'SUCCESS'
AND v.template_id = #{query.templateId}
AND t.inspection_order_id = #{query.inspectionOrderId}
ORDER BY t.end_time DESC, t.id DESC

SELECT t.id AS taskId, t.report_no AS reportNo, t.status AS status, t.message AS reportRemark, t.lifecycle_status AS lifecycleStatus, t.report_approval_process_instance_id AS processInstanceId, v.template_id AS templateId, t.template_version_id AS templateVersionId, v.version_no AS templateVersionNo, rt.name AS templateName, t.path AS path, t.end_time AS endTime, t.report_approved AS reportApproved, t.report_approval_time AS reportApprovalTime, t.create_by AS generatedBy FROM lm_report_generate_task t LEFT JOIN lm_report_template_version v ON v.id = t.template_version_id LEFT JOIN lm_report_template rt ON rt.id = v.template_id
t.is_deleted = 0 AND t.status = 'SUCCESS' AND t.inspection_order_id = #{orderId} AND v.template_id = #{templateId}
ORDER BY t.end_time DESC, t.id DESC

SELECT * FROM lm_report_generate_task
WHERE is_deleted = 0 AND inspection_order_id = #{orderId}
ORDER BY create_time DESC

mapper.update:
UPDATE lm_report_generate_task t
SET t.lifecycle_status = 'VOIDED', t.update_time = NOW()
WHERE t.is_deleted = 0
  AND t.inspection_order_id = #{orderId}
  AND t.lifecycle_status = 'EFFECTIVE'
  AND (#{excludeTaskId} IS NULL OR t.id <> #{excludeTaskId})
  AND t.template_version_id IN (
    SELECT v.id FROM lm_report_template_version v WHERE v.template_id = #{templateId}
  )
